/// All primes from 2 to `n` inclusive, ascending (trial division).
pub fn primes_up_to(n: Int) -> List[Int] {
  var out: List[Int] = []
  for k in range(2, n + 1) {
    var is_p = true
    var d = 2
    while d * d <= k {
      if k % d == 0 {
        is_p = false
        break
      }
      d = d + 1
    }
    if is_p {
      out = out.push(k)
    }
  }
  return out
}
